'use strict';

// --- time.js ---
// @ts-check
// Time formatting for the display. Pure, no DOM.

/** @param {number} n */
const pad = (n) => String(n).padStart(2, '0');

/**
 * `m:ss`, or `h:mm:ss` past one hour. Anything that is not a non-negative
 * finite number reads as `0:00`, so a missing duration never breaks the text.
 * @param {unknown} ms
 * @returns {string}
 */
function formatTime(ms) {
  if (typeof ms !== 'number' || !Number.isFinite(ms) || ms < 0) return '0:00';
  const total = Math.floor(ms / 1000);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  return h > 0 ? `${h}:${pad(m)}:${pad(s)}` : `${m}:${pad(s)}`;
}

// --- marquee.js ---
// @ts-check
// Text of the display and the scroll step. Pure, no DOM: the DOM side that
// measures the display and drives the timer lives in marquee-dom.js.

// Winamp put this between the end of the text and its next lap.
const SEPARATOR = '  ***  ';

/**
 * @typedef {object} Track
 * @property {string} artist
 * @property {string} title
 * @property {number} durationMs
 */

/**
 * Reduces Spicetify's player item to what the display needs. Every read is
 * optional so a missing item, a podcast without artists or a local file
 * without metadata still yields something to show.
 * @param {Partial<Spicetify.PlayerTrack> | undefined | null} item
 * @returns {Track}
 */
function describeItem(item) {
  const artists = item?.artists?.map((artist) => artist.name).filter(Boolean) ?? [];
  return {
    artist: artists.length > 0 ? artists.join(', ') : (item?.metadata?.artist_name ?? ''),
    title: item?.name ?? item?.metadata?.title ?? '',
    durationMs: item?.duration?.milliseconds ?? 0,
  };
}

/**
 * `ARTIST - TITLE (m:ss)`, uppercase. Without an artist only the title; with
 * nothing at all, the word WINAMP, which is what an idle Winamp showed.
 * @param {Track} track
 * @returns {string}
 */
function displayText({ artist, title, durationMs }) {
  const a = artist.trim();
  const t = title.trim();
  const base = a && t ? `${a} - ${t}` : t || a || 'WINAMP';
  const time = durationMs > 0 ? ` (${formatTime(durationMs)})` : '';
  return `${base}${time}`.toUpperCase();
}

/**
 * The window of `width` characters visible at `offset`, and the offset for
 * the next step. Text that fits is returned whole with the offset pinned at
 * zero; text that does not fit scrolls through `text + SEPARATOR` and wraps.
 * @param {string} text
 * @param {number} offset
 * @param {number} width
 * @returns {{ view: string, offset: number }}
 */
function scrollStep(text, offset, width) {
  if (width <= 0) return { view: '', offset: 0 };
  if (text.length <= width) return { view: text, offset: 0 };
  const loop = text + SEPARATOR;
  const start = offset % loop.length;
  return { view: (loop + loop).slice(start, start + width), offset: (start + 1) % loop.length };
}

// --- spectrum.js ---
// @ts-check
// State of the spectrum analyser. Pure, no DOM: drawing and scheduling live
// in spectrum-dom.js. Values are 0..1 fractions of the full bar height.

// 3 px bars with 1 px gaps in a 76 px canvas, the geometry of Winamp's own
// analyser (19 bands in 75 px).
const BARS = 19;
// Rows of 1 px in the 16 px canvas; the colour bands are counted in rows.
const ROWS = 16;
// How much a bar drops per frame when its target is lower.
const DECAY = 0.06;
// Weight of the previous target when a new random target comes in.
const SMOOTHING = 0.7;
// Frames a peak waits above a lower bar before it starts to fall.
const PEAK_HOLD = 15;
// How much a peak drops per frame once the hold is over.
const PEAK_FALL = 0.02;

const BANDS = /** @type {const} */ (['green', 'yellow', 'orange', 'red']);

/**
 * @typedef {typeof BANDS[number]} Band
 * @typedef {{ values: number[], targets: number[], peaks: number[], holds: number[] }} SpectrumState
 */

/**
 * @param {number} [bars]
 * @returns {SpectrumState}
 */
function createState(bars = BARS) {
  const zeros = () => new Array(bars).fill(0);
  return { values: zeros(), targets: zeros(), peaks: zeros(), holds: zeros() };
}

/**
 * Advances every bar by one frame, in place. While playing each bar chases a
 * smoothed random target, jumping up at once and falling at a fixed rate;
 * paused, the target is zero and everything decays. The peak rides on the
 * bar, holds for PEAK_HOLD frames once the bar drops under it, then falls.
 * @param {SpectrumState} state
 * @param {() => number} rng returns 0..1
 * @param {boolean} playing
 * @returns {SpectrumState}
 */
function nextFrame(state, rng, playing) {
  const { values, targets } = state;
  for (let i = 0; i < values.length; i += 1) {
    const target = playing ? SMOOTHING * (targets[i] ?? 0) + (1 - SMOOTHING) * rng() : 0;
    targets[i] = target;
    const value = values[i] ?? 0;
    values[i] = target > value ? target : Math.max(0, value - DECAY);
  }
  trackPeaks(state);
  return state;
}

/**
 * Moves the peak of every bar for one frame: it rides on the bar, holds for
 * PEAK_HOLD frames once the bar drops under it, then falls. Takes only what it
 * reads, so any list of values can have peaks, not just a spectrum's own.
 * @param {{ values: number[], peaks: number[], holds: number[] }} state
 */
function trackPeaks({ values, peaks, holds }) {
  for (let i = 0; i < values.length; i += 1) {
    const current = values[i] ?? 0;
    const peak = peaks[i] ?? 0;
    if (current >= peak) {
      peaks[i] = current;
      holds[i] = PEAK_HOLD;
    } else if ((holds[i] ?? 0) > 0) {
      holds[i] = (holds[i] ?? 0) - 1;
    } else {
      peaks[i] = Math.max(0, peak - PEAK_FALL);
    }
  }
}

/**
 * Colour band of a row counted from the bottom: the lowest quarter green,
 * then yellow, orange and red at the top.
 * @param {number} row
 * @param {number} totalRows
 * @returns {Band}
 */
function colorForRow(row, totalRows) {
  const band = Math.min(3, Math.max(0, Math.floor((row / totalRows) * 4)));
  return BANDS[band] ?? 'green';
}

/**
 * True when nothing is left to animate: every bar and every peak at zero.
 * @param {SpectrumState} state
 * @returns {boolean}
 */
function isIdle(state) {
  return state.values.every((v) => v === 0) && state.peaks.every((p) => p === 0);
}

// --- visualizer-settings.js ---
// @ts-check
// Settings of the visualizer. Pure, no DOM: the profile menu window and the
// surfaces read and change them through the store, so one change reaches all.

const SETTINGS_KEY = 'winamp-classic:visualizer';

const STYLE_IDS = /** @type {const} */ (['bars', 'scope', 'glow']);

/**
 * @typedef {typeof STYLE_IDS[number]} StyleId
 * @typedef {{
 *   enabled: boolean,
 *   style: StyleId,
 *   fullscreen: boolean,
 *   sidebar: boolean,
 *   sidebarOpen: boolean,
 *   miniplayer: boolean,
 * }} VisualizerSettings
 */

/** @type {VisualizerSettings} */
const DEFAULTS = {
  enabled: false,
  style: 'bars',
  fullscreen: true,
  sidebar: true,
  sidebarOpen: true,
  miniplayer: true,
};

/**
 * Turns whatever was stored into valid settings, field by field: a bad value
 * costs only that field, never the rest.
 * @param {unknown} raw
 * @returns {VisualizerSettings}
 */
function normalizeSettings(raw) {
  const source = raw !== null && typeof raw === 'object' ? /** @type {Record<string, unknown>} */ (raw) : {};
  /** @param {'enabled' | 'fullscreen' | 'sidebar' | 'sidebarOpen' | 'miniplayer'} key */
  const flag = (key) => (typeof source[key] === 'boolean' ? /** @type {boolean} */ (source[key]) : DEFAULTS[key]);
  const style = STYLE_IDS.find((id) => id === source.style) ?? DEFAULTS.style;
  return {
    enabled: flag('enabled'),
    style,
    fullscreen: flag('fullscreen'),
    sidebar: flag('sidebar'),
    sidebarOpen: flag('sidebarOpen'),
    miniplayer: flag('miniplayer'),
  };
}

/**
 * @typedef {{ get(key: string): string | null, set(key: string, value: string): void }} Storage
 */

/**
 * @param {Storage} storage
 * @returns {unknown} the parsed value, or null when it is missing or not JSON
 */
function readStored(storage) {
  try {
    return JSON.parse(storage.get(SETTINGS_KEY) ?? 'null');
  } catch {
    return null;
  }
}

/**
 * @param {{ storage: Storage }} options
 * @returns {{
 *   get(): VisualizerSettings,
 *   set(patch: Partial<VisualizerSettings>): void,
 *   subscribe(listener: (settings: VisualizerSettings) => void): () => void,
 * }}
 */
function createSettingsStore({ storage }) {
  let current = normalizeSettings(readStored(storage));
  /** @type {Set<(settings: VisualizerSettings) => void>} */
  const listeners = new Set();

  return {
    get: () => ({ ...current }),
    set(patch) {
      current = normalizeSettings({ ...current, ...patch });
      try {
        storage.set(SETTINGS_KEY, JSON.stringify(current));
      } catch {
        // Storage can be full or blocked; the change still holds in memory.
      }
      for (const listener of listeners) listener({ ...current });
    },
    subscribe(listener) {
      listeners.add(listener);
      return () => void listeners.delete(listener);
    },
  };
}

// --- visualizer-signal.js ---
// @ts-check
// The synthetic signal behind every visualizer style. Pure, no DOM. It is not
// the playing audio (Spotify gives the page no way to hear it): the bars come
// from the same generator as the display spectrum in spectrum.js, so the big
// one is as lively as the small one, and a tempo taken from the track id gives
// the beat that the oscilloscope and the glow follow.

// Enough bands for a full-width bar every few pixels; narrower canvases take fewer.
const BAND_COUNT = 256;
const WAVE_SAMPLES = 64;

// Used when there is no track uri to take a tempo from.
const DEFAULT_BPM = 120;
const MIN_BPM = 80;
const BPM_SPAN = 71;
// How fast the beat envelope falls inside one beat period.
const BEAT_FALL = 5;
// Per-step factors for the paused decay of the beat and the waveform.
const BEAT_RELEASE = 0.85;
const WAVE_RELEASE = 0.8;
// Below this a decaying value snaps to exactly 0, so silence is reachable.
const FLOOR = 0.002;
// A band is its place on a broad curve (as many bars as the small spectrum,
// interpolated between neighbours) plus a jitter of its own, each swinging
// around the middle. The two spreads add up to more than 1 so the mix is as
// lively as one generator on its own would be.
const COARSE_SPREAD = 0.8;
const FINE_SPREAD = 0.9;

/**
 * levels: 0..1 per band. peaks: the held peak of each band. wave: -1..1 samples
 * of a waveform. beat: 0..1, 1 on the beat. coarse and fine are the two
 * spectrum states the levels are mixed from, holds the peak timers; all three
 * are internal to stepSignal.
 * @typedef {{
 *   levels: number[],
 *   peaks: number[],
 *   wave: number[],
 *   beat: number,
 *   coarse: import('./spectrum.js').SpectrumState,
 *   fine: import('./spectrum.js').SpectrumState,
 *   holds: number[],
 * }} Signal
 */

/**
 * A tempo between 80 and 150 BPM derived from the track uri, so the same
 * track always beats the same way.
 * @param {string | undefined} uri
 * @returns {number}
 */
function bpmForTrack(uri) {
  if (!uri) return DEFAULT_BPM;
  let hash = 0;
  for (let i = 0; i < uri.length; i += 1) hash = (hash * 31 + uri.charCodeAt(i)) >>> 0;
  return MIN_BPM + (hash % BPM_SPAN);
}

/** @returns {Signal} */
function createSignal() {
  return {
    levels: new Array(BAND_COUNT).fill(0),
    peaks: new Array(BAND_COUNT).fill(0),
    wave: new Array(WAVE_SAMPLES).fill(0),
    beat: 0,
    coarse: createState(BARS),
    fine: createState(BAND_COUNT),
    holds: new Array(BAND_COUNT).fill(0),
  };
}

/**
 * Advances the signal by one frame, in place.
 * @param {Signal} signal
 * @param {{ uri?: string, progressMs: number, playing: boolean, rng: () => number }} input
 * @returns {Signal}
 */
function stepSignal(signal, { uri, progressMs, playing, rng }) {
  const progress = Number.isFinite(progressMs) && progressMs > 0 ? progressMs : 0;
  const period = 60000 / bpmForTrack(uri);
  const phase = (progress % period) / period;

  if (playing) {
    signal.beat = Math.exp(-BEAT_FALL * phase);
  } else {
    signal.beat = signal.beat * BEAT_RELEASE < FLOOR ? 0 : signal.beat * BEAT_RELEASE;
  }

  nextFrame(signal.coarse, rng, playing);
  nextFrame(signal.fine, rng, playing);
  for (let i = 0; i < BAND_COUNT; i += 1) {
    if (playing) {
      const at = (i / (BAND_COUNT - 1)) * (BARS - 1);
      const low = Math.floor(at);
      const high = Math.min(BARS - 1, low + 1);
      const across = at - low;
      const broad = (signal.coarse.values[low] ?? 0) * (1 - across) + (signal.coarse.values[high] ?? 0) * across;
      const mixed = 0.5 + COARSE_SPREAD * (broad - 0.5) + FINE_SPREAD * ((signal.fine.values[i] ?? 0) - 0.5);
      signal.levels[i] = Math.min(1, Math.max(0, mixed));
    } else {
      signal.levels[i] = Math.max(0, (signal.levels[i] ?? 0) - DECAY);
    }
  }
  trackPeaks({ values: signal.levels, peaks: signal.peaks, holds: signal.holds });

  const seconds = progress / 1000;
  const amplitude = 0.25 + 0.6 * signal.beat;
  for (let i = 0; i < WAVE_SAMPLES; i += 1) {
    if (playing) {
      const x = i / WAVE_SAMPLES;
      const carrier = 0.7 * Math.sin(2 * Math.PI * (2 * x + seconds)) + 0.3 * Math.sin(2 * Math.PI * (5 * x + 1.3 * seconds));
      const value = amplitude * carrier + 0.08 * (rng() - 0.5);
      signal.wave[i] = Math.max(-1, Math.min(1, value));
    } else {
      const released = (signal.wave[i] ?? 0) * WAVE_RELEASE;
      signal.wave[i] = Math.abs(released) < FLOOR ? 0 : released;
    }
  }
  return signal;
}

/**
 * True when nothing is left to animate.
 * @param {Signal} signal
 * @returns {boolean}
 */
function isSilent(signal) {
  return signal.beat === 0 && signal.levels.every((v) => v === 0) && signal.peaks.every((p) => p === 0) && signal.wave.every((v) => v === 0);
}

// --- visualizer-styles.js ---
// @ts-check
// How each visualizer style paints one frame of the signal. Pure drawing on a
// 2D context, no DOM and no scheduling: the loop decides when, the surfaces
// decide where.

// Theme token per colour, with the scheme's own value as the fallback when
// the token cannot be read (a detached canvas, or a test without the sheet).
const VIZ_COLOR_TOKENS = /** @type {const} */ ({
  low: ['--spice-text', '#00ff00'],
  mid: ['--wa-vol-mid', '#ffff00'],
  high: ['--spice-notification-error', '#c60000'],
  accent: ['--spice-misc', '#ff9900'],
  back: ['--spice-main', '#000000'],
  peak: ['--wa-bevel-light', '#5a5a6e'],
});

/** @typedef {Record<keyof typeof VIZ_COLOR_TOKENS, string>} VizColors */

/**
 * The slice of CanvasRenderingContext2D the styles use, so tests can pass a fake.
 * @typedef {Pick<CanvasRenderingContext2D,
 *   'clearRect' | 'fillRect' | 'beginPath' | 'moveTo' | 'lineTo' | 'stroke' | 'arc' | 'fill' |
 *   'fillStyle' | 'strokeStyle' | 'lineWidth' | 'globalAlpha'>} DrawContext
 */

/**
 * @param {HTMLElement} el
 * @returns {VizColors}
 */
function readVisualizerColors(el) {
  const style = getComputedStyle(el);
  const entries = Object.entries(VIZ_COLOR_TOKENS).map(([name, [token, fallback]]) => [name, style.getPropertyValue(token).trim() || fallback]);
  return /** @type {VizColors} */ (Object.fromEntries(entries));
}

/** @param {number} value @returns {number} */
function unit(value) {
  return Number.isFinite(value) ? Math.min(1, Math.max(0, value)) : 0;
}

// About one bar per this many CSS pixels, so a wide canvas gets thin bars
// instead of the same few stretched.
const BAR_TARGET_W = 6;
const MIN_BARS = 16;

/**
 * How many bars fit a canvas of this width, one signal band each at most.
 * @param {number} width in CSS pixels
 * @returns {number}
 */
function barCountFor(width) {
  return Math.min(BAND_COUNT, Math.max(MIN_BARS, Math.round(width / BAR_TARGET_W)));
}

// The four colour bands of a bar, bottom to top, the same as the display spectrum's.
const BAR_BANDS = /** @type {const} */ (['low', 'mid', 'accent', 'high']);
// Thickness of the peak cap, in CSS pixels.
const PEAK_CAP_H = 2;

/**
 * Winamp-style columns, painted like the display spectrum: each bar reads one
 * band (not an average, which would iron the randomness out), is split into four
 * colour bands by height and wears the held peak as a cap.
 * @type {StyleDraw}
 */
function drawBars(ctx, signal, { w, h }, colors) {
  const count = barCountFor(w);
  const slot = w / count;
  const barW = Math.max(1, slot - 1);
  for (let i = 0; i < count; i += 1) {
    const band = Math.floor((i * BAND_COUNT) / count);
    const x = i * slot;
    const total = unit(signal.levels[band] ?? 0) * h;
    for (let k = 0; k < BAR_BANDS.length && total > 0; k += 1) {
      const bottom = (k / BAR_BANDS.length) * h;
      const top = Math.min(total, ((k + 1) / BAR_BANDS.length) * h);
      if (top <= bottom) break;
      ctx.fillStyle = colors[BAR_BANDS[k] ?? 'low'];
      ctx.fillRect(x, h - top, barW, top - bottom);
    }
    const peak = unit(signal.peaks[band] ?? 0) * h;
    if (peak > 0) {
      ctx.fillStyle = colors.peak;
      ctx.fillRect(x, Math.min(h - PEAK_CAP_H, Math.max(0, h - peak)), barW, PEAK_CAP_H);
    }
  }
}

/** The oscilloscope: one line through the waveform samples. @type {StyleDraw} */
function drawScope(ctx, signal, { w, h }, colors) {
  ctx.strokeStyle = colors.low;
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (let i = 0; i < WAVE_SAMPLES; i += 1) {
    const x = (i / (WAVE_SAMPLES - 1)) * w;
    const y = h / 2 - Math.max(-1, Math.min(1, Number.isFinite(signal.wave[i]) ? (signal.wave[i] ?? 0) : 0)) * (h / 2);
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.stroke();
}

/** A soft pulse on the beat with a ring of dots that follow the bands. @type {StyleDraw} */
function drawGlow(ctx, signal, { w, h }, colors) {
  const cx = w / 2;
  const cy = h / 2;
  const reach = Math.min(w, h) / 2;
  const beat = unit(signal.beat);
  if (beat > 0) {
    ctx.fillStyle = colors.accent;
    ctx.globalAlpha = 0.15 + 0.5 * beat;
    ctx.beginPath();
    ctx.arc(cx, cy, reach * (0.25 + 0.5 * beat), 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.fillStyle = colors.low;
  const dots = 32;
  for (let d = 0; d < dots; d += 1) {
    const level = unit(signal.levels[Math.floor((d * BAND_COUNT) / dots)] ?? 0);
    if (level <= 0) continue;
    const angle = (d / dots) * Math.PI * 2;
    const radius = reach * (0.45 + 0.5 * level);
    ctx.globalAlpha = 0.35 + 0.65 * level;
    ctx.beginPath();
    ctx.arc(cx + Math.cos(angle) * radius, cy + Math.sin(angle) * radius, 2 + 3 * level, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

/**
 * @callback StyleDraw
 * @param {DrawContext} ctx
 * @param {import('./visualizer-signal.js').Signal} signal
 * @param {{ w: number, h: number }} size
 * @param {VizColors} colors
 * @returns {void}
 */

/** @type {Record<string, StyleDraw>} */
const STYLE_DRAWERS = { bars: drawBars, scope: drawScope, glow: drawGlow };

/**
 * Clears the canvas and paints the style. An unknown id paints bars.
 * @param {string} id
 * @param {DrawContext} ctx
 * @param {import('./visualizer-signal.js').Signal} signal
 * @param {{ w: number, h: number }} size
 * @param {VizColors} colors
 */
function drawStyle(id, ctx, signal, size, colors) {
  ctx.clearRect(0, 0, size.w, size.h);
  (STYLE_DRAWERS[id] ?? drawBars)(ctx, signal, size, colors);
}

// --- dom.js ---
// @ts-check
// The one module that touches the DOM and the Spicetify globals. The other
// modules in src/ stay pure so they can be tested without a browser.
//
// An injection is a small feature (marquee, spectrum, title bar) that mounts
// into the display of the now playing bar. Each one runs in isolation: a
// throw is logged with the theme prefix and the next injection still runs.

/**
 * @typedef {object} Injection
 * @property {string} name
 * @property {(display: HTMLElement) => void} run
 * @property {(display: HTMLElement) => void} [cleanup]
 */

const LOG_PREFIX = '[winamp-classic]';

// The display is the track info block that user.css turns into the LED
// panel. It only exists while something is playing.
//
// Spotify 1.3.5 dropped the readable class names (they came from the Spicetify
// class map, which does not cover every Spotify version), so this hangs on what
// Spotify keeps: the now-playing-widget test id (`-v2` since 1.3.6, and both ids are
// still in the bundle, so the theme names both) and the shape of the widget. The
// widget holds the cover (it has a test id), the text block and the action
// buttons; the text block is the child with neither a test id nor a button.
const DISPLAY_SELECTOR =
  '[data-testid="now-playing-bar"] :is([data-testid="now-playing-widget"], [data-testid="now-playing-widget-v2"]) > div:not([data-testid], :has(button))';

// The stable parent of the bar. Spotify remounts the bar inside it in some
// flows, so this is what the observer watches.
const BAR_SELECTOR = '[data-testid="now-playing-bar"]';

// The inner bar that holds the three columns. The outer testid element is an
// ASIDE container; this DIV is where bar-wide strips belong.
const NOW_PLAYING_BAR_SELECTOR = `${BAR_SELECTOR} > div`;

/** @returns {boolean} */
function isSpicetifyReady() {
  return typeof Spicetify !== 'undefined' && Boolean(Spicetify.Player) && Boolean(Spicetify.Platform);
}

/**
 * Resolves once `isReady` reports true, polling on a timer. Rejects after
 * `timeoutMs` so a broken Spicetify never leaves the poll running forever.
 * @param {{ isReady?: () => boolean, intervalMs?: number, timeoutMs?: number }} [options]
 * @returns {Promise<void>}
 */
function waitForSpicetify({ isReady = isSpicetifyReady, intervalMs = 100, timeoutMs = 30000 } = {}) {
  return new Promise((resolve, reject) => {
    const started = Date.now();
    const poll = () => {
      if (isReady()) {
        resolve();
        return;
      }
      if (Date.now() - started >= timeoutMs) {
        reject(new Error(`Spicetify not ready after ${Math.round(timeoutMs / 1000)}s`));
        return;
      }
      setTimeout(poll, intervalMs);
    };
    poll();
  });
}

/**
 * @param {ParentNode} [root]
 * @returns {HTMLElement | null}
 */
function findDisplay(root = document) {
  return root.querySelector(DISPLAY_SELECTOR);
}

/**
 * Runs every injection against the display. Returns the ones whose `run` did
 * not throw, which is the set that later needs a cleanup.
 * @param {Injection[]} injections
 * @param {HTMLElement} display
 * @returns {Injection[]}
 */
function runInjections(injections, display) {
  return injections.filter((injection) => {
    try {
      injection.run(display);
      return true;
    } catch (err) {
      console.warn(`${LOG_PREFIX} ${injection.name}:`, err);
      return false;
    }
  });
}

/**
 * @param {Injection[]} injections
 * @param {HTMLElement} display
 */
function cleanupInjections(injections, display) {
  for (const injection of injections) {
    try {
      injection.cleanup?.(display);
    } catch (err) {
      console.warn(`${LOG_PREFIX} ${injection.name} cleanup:`, err);
    }
  }
}

/**
 * Mounts the injections into the display and keeps them mounted: a
 * MutationObserver on the bar re-runs them whenever the display element is
 * replaced, appears or goes away. Cleanup always runs before a new round, so
 * nothing gets duplicated.
 * @param {Injection[]} injections
 * @param {{ root?: Document }} [options]
 * @returns {{ remount: () => void, disconnect: () => void }}
 */
function mount(injections, { root = document } = {}) {
  /** @type {HTMLElement | null} */
  let display = null;
  /** @type {Injection[]} */
  let mounted = [];

  const sync = () => {
    const next = findDisplay(root);
    if (next === display) return;
    if (display) cleanupInjections(mounted, display);
    display = next;
    mounted = display ? runInjections(injections, display) : [];
  };

  const bar = root.querySelector(BAR_SELECTOR);
  const observer = new MutationObserver(sync);
  observer.observe(bar ?? root.body, { childList: true, subtree: true });

  sync();
  if (!display) console.warn(`${LOG_PREFIX} display not found, waiting for it`);

  return { remount: sync, disconnect: () => observer.disconnect() };
}

// --- visualizer-loop.js ---
// @ts-check
// The one animation loop every visualizer surface shares. It steps the
// synthetic signal once per frame and hands it to each visible surface, and it
// only runs while there is something to show: a visible surface, a visible
// window, and music playing or a signal still fading out.

/**
 * Something that shows the visualizer: a canvas on a Spotify surface.
 * @typedef {object} Surface
 * @property {string} name
 * @property {() => boolean} isVisible whether it is on screen and switched on
 * @property {() => boolean} isConnected false once Spotify detached its canvas
 * @property {(signal: import('./visualizer-signal.js').Signal) => void} draw
 */

/**
 * The slice of Spicetify.Player the loop uses, so tests can pass a fake.
 * @typedef {{ isPlaying(): boolean, getProgress(): number }} LoopPlayer
 */

/**
 * @param {{
 *   player: () => LoopPlayer,
 *   getUri: () => string | undefined,
 *   schedule?: (callback: () => void) => number,
 *   cancel?: (id: number) => void,
 *   rng?: () => number,
 *   isHidden?: () => boolean,
 *   reducedMotion?: () => boolean,
 * }} options
 * @returns {{ register(surface: Surface): () => void, wake(): void, retarget(): void, stop(): void, isRunning(): boolean }}
 */
function createVisualizerLoop({
  player,
  getUri,
  schedule = (callback) => requestAnimationFrame(callback),
  cancel = (id) => cancelAnimationFrame(id),
  rng = Math.random,
  isHidden = () => typeof document !== 'undefined' && document.hidden,
  reducedMotion = () => typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches,
}) {
  const signal = createSignal();
  /** @type {Set<Surface>} */
  const surfaces = new Set();
  /** @type {number | null} */
  let pending = null;

  // origin._state sits behind a getter that can be undefined for a moment.
  const playing = () => {
    try {
      return player().isPlaying();
    } catch {
      return false;
    }
  };

  const progress = () => {
    try {
      return player().getProgress();
    } catch {
      return 0;
    }
  };

  const anyVisible = () => [...surfaces].some((surface) => surface.isConnected() && surface.isVisible());

  const frame = () => {
    pending = null;
    for (const surface of [...surfaces]) {
      if (!surface.isConnected()) surfaces.delete(surface);
    }
    stepSignal(signal, { uri: getUri(), progressMs: progress(), playing: playing(), rng });
    for (const surface of [...surfaces]) {
      if (!surface.isVisible()) continue;
      try {
        surface.draw(signal);
      } catch (err) {
        console.warn(`${LOG_PREFIX} visualizer: ${surface.name} failed to draw, dropping it`, err);
        surfaces.delete(surface);
      }
    }
    if (!reducedMotion() && shouldRun()) pending = schedule(frame);
  };

  const shouldRun = () => !isHidden() && anyVisible() && (playing() || !isSilent(signal));

  const wake = () => {
    if (pending !== null) return;
    if (reducedMotion()) {
      // A still picture: one frame per wake, no continuation.
      if (!isHidden() && anyVisible()) frame();
      return;
    }
    if (shouldRun()) pending = schedule(frame);
  };

  return {
    register(surface) {
      surfaces.add(surface);
      wake();
      return () => void surfaces.delete(surface);
    },
    wake,
    // Drops the pending frame and asks for a new one. The pending frame lives on
    // one window; when the window that paces the loop changes (Spotify goes to
    // the background, the miniplayer opens or closes) it may never run, and a
    // plain wake() would see it as pending and do nothing.
    retarget() {
      if (pending !== null) cancel(pending);
      pending = null;
      wake();
    },
    stop() {
      if (pending !== null) cancel(pending);
      pending = null;
    },
    isRunning: () => pending !== null,
  };
}

